package com.etpms;
import com.etpms.dao.UserDAO;import com.etpms.model.User;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;
@WebServlet(urlPatterns={"/login","/logout"}) public class LoginServlet extends HttpServlet {private final UserDAO dao=new UserDAO();protected void doGet(HttpServletRequest q,HttpServletResponse p)throws IOException,ServletException{if(q.getServletPath().equals("/logout")){HttpSession s=q.getSession(false);if(s!=null)s.invalidate();p.sendRedirect(q.getContextPath()+"/login");return;}q.getRequestDispatcher("/WEB-INF/views/login.jsp").forward(q,p);}protected void doPost(HttpServletRequest q,HttpServletResponse p)throws IOException,ServletException{String name=q.getParameter("username"),pass=q.getParameter("password");try{User u=dao.authenticate(name==null?"":name.trim(),pass==null?"":pass);if(u==null){q.setAttribute("error","Invalid username or password.");q.getRequestDispatcher("/WEB-INF/views/login.jsp").forward(q,p);return;}HttpSession old=q.getSession(false);if(old!=null)old.invalidate();HttpSession s=q.getSession(true);s.setMaxInactiveInterval(30*60);s.setAttribute("user",u);s.setAttribute("role",u.role);p.sendRedirect(q.getContextPath()+"/dashboard");}catch(Exception e){throw new ServletException(e);}}}
